```java
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import org.apache.commons.io.SerializationUtils;
import java.io.ObjectInputFilter;

public class SecureServer {
    public void startServer() throws IOException {
        ServerSocket serverSocket = new ServerSocket(8080);
        while (true) {
            try (Socket socket = serverSocket.accept();
                 ObjectInputStream ois = new ObjectInputStream(socket.getInputStream())) {

                // FIX: Implement an ObjectInputFilter to allow only specific, safe classes.
                // This prevents an attacker from instating arbitrary gadgets in the classpath.
                ObjectInputFilter filter = ObjectInputFilter.Config.createFilter("com.myapp.models.*;java.base/*;!*");
                ois.setObjectInputFilter(filter);

                Object obj = ois.readObject();
                System.out.println("Received safely: " + obj.toString());

            } catch (ClassNotFoundException e) {
                e.printStackTrace();
            } catch (InvalidClassException e) {
                System.err.println("Blocked unauthorized deserialization attempt!");
            }
        }
    }
}
```

